WITH valid_web_events AS (SELECT *, SUBSTRING(page, 1, 3) page_prefix FROM web_events WHERE session_id = 1 AND event_time < '2025-07-13'), summary AS (SELECT HOUR(event_time) event_hour, ROUND((100 * SUM(CASE WHEN event_type = 'search' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_search, MIN(duration_sec) min_duration_sec FROM valid_web_events GROUP BY HOUR(event_time)) SELECT event_hour, pct_search, min_duration_sec FROM summary WHERE pct_search >= 75 ORDER BY min_duration_sec DESC;
